/** Devuelve los bytes del stream de cuadros. */
export function badappleBytes() {
  const bin = atob(PARTES.join(''));
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
